CREATE TEMP TABLE hakim_inherited_results ON COMMIT DROP AS SELECT id,fixture_id,status,revision,home_score,away_score,forfeit_side FROM jsonb_populate_recordset(null::public.result_versions,'[{"id":"ee9f7b8d-64cc-4d4c-b9f1-af3c034efaef","status":"published","revision":1,"away_score":0,"home_score":5,"forfeit_side":null,"fixture_id":"b6b1a297-478a-4e71-a674-4228f2f11107"},{"id":"e55298a0-cd6c-4e27-998e-1926b7f110bc","status":"published","revision":1,"away_score":3,"home_score":11,"forfeit_side":null,"fixture_id":"476130fb-c05c-4fc3-ae64-b1d6f74ba84b"},{"id":"3a8c4980-655d-470a-b7a7-0a3c44b10987","status":"published","revision":1,"away_score":5,"home_score":0,"forfeit_side":"home","fixture_id":"597d5f34-669b-4d99-87ec-f6ce298ca5c8"}]'::jsonb);
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND season_id='ba8c0e2f-7f8a-41be-8ddb-65b320cebaa2' AND lifecycle='active' AND publication_state='published') THEN RAISE EXCEPTION 'Monday edition changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.teams WHERE id='f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c' OR(competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND (legacy_id='mon-hakims-team' OR lower(btrim(name))='hakim''s team'))) THEN RAISE EXCEPTION 'Hakim identity already exists; stop, do not duplicate'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.teams WHERE id='aae18510-0f33-494b-8962-d7a5e86d0bf0' AND competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND name='Imole United' AND legacy_id='mon-imole' AND status='active' AND standings_eligible AND profile_version=3 AND updated_at='2026-10-16T06:11:40.510035+00:00'::timestamptz) THEN RAISE EXCEPTION 'Imole profile changed'; END IF;
 IF (SELECT count(*)FROM public.teams WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status='active' AND standings_eligible)<>16 THEN RAISE EXCEPTION 'Monday roster changed'; END IF;
 IF EXISTS(SELECT 1 FROM public.fixture_change_sets WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status IN('draft','pending_review')) THEN RAISE EXCEPTION 'Pending fixture work requires reconciliation'; END IF;
 IF EXISTS(SELECT 1 FROM public.standing_adjustments WHERE team_id='aae18510-0f33-494b-8962-d7a5e86d0bf0') THEN RAISE EXCEPTION 'Reconcile Imole standing adjustments first'; END IF;
 IF (SELECT count(*)FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled')<>240 OR EXISTS(SELECT 1 FROM hakim_baseline b LEFT JOIN public.fixtures f USING(id) WHERE row(f.id,f.competition_season_id,f.round_number,f.round_label,f.match_date,f.kickoff_time,f.court,f.home_team_id,f.away_team_id,f.schedule_version,f.updated_at,f.publication_state,f.schedule_status,f.stage,f.legacy_id) IS DISTINCT FROM row(b.id,b.competition_season_id,b.round_number,b.round_label,b.match_date,b.kickoff_time,b.court,b.home_team_id,b.away_team_id,b.schedule_version,b.updated_at,b.publication_state,b.schedule_status,b.stage,b.legacy_id)) THEN RAISE EXCEPTION 'Published Monday baseline changed'; END IF;
 IF EXISTS(SELECT 1 FROM hakim_changes c JOIN public.fixtures f USING(id) JOIN public.result_versions v ON v.fixture_id=f.id WHERE f.round_number>=4) THEN RAISE EXCEPTION 'Future fixture has result work; stop'; END IF;
 IF (SELECT count(*) FROM public.fixtures f JOIN public.result_versions v ON v.fixture_id=f.id WHERE f.competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND 'aae18510-0f33-494b-8962-d7a5e86d0bf0' IN(f.home_team_id,f.away_team_id))<>3 THEN RAISE EXCEPTION 'Inherited result count changed'; END IF;
 IF EXISTS(SELECT 1 FROM hakim_inherited_results b LEFT JOIN public.result_versions v USING(id) WHERE row(v.id,v.fixture_id,v.status,v.revision,v.home_score,v.away_score,v.forfeit_side) IS DISTINCT FROM row(b.id,b.fixture_id,b.status,b.revision,b.home_score,b.away_score,b.forfeit_side)) THEN RAISE EXCEPTION 'Inherited result baseline changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.standings WHERE team_id='aae18510-0f33-494b-8962-d7a5e86d0bf0' AND played=3 AND wins=0 AND draws=0 AND losses=3 AND goals_for=3 AND goals_against=21 AND points=0) THEN RAISE EXCEPTION 'Inherited record changed'; END IF;
END $$;
CREATE TEMP TABLE hakim_protected ON COMMIT DROP AS select 'results' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.result_versions x where true
union all
select 'fixtures' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.fixtures x where id not in(select id from hakim_changes)
union all
select 'teams' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.teams x where id<>'aae18510-0f33-494b-8962-d7a5e86d0bf0'
union all
select 'adjustments' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.standing_adjustments x where true
union all
select 'preferences' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.team_kickoff_preferences x where true
union all
select 'notes' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by team_id)::text,'[]')) hash from public.team_fixture_notes x where true
union all
select 'editions' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.competition_seasons x where true
union all
select 'seasons' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.seasons x where true;
CREATE TEMP TABLE hakim_audit_before ON COMMIT DROP AS SELECT id,to_jsonb(a) preserved FROM public.admin_audit_log a;
CREATE TEMP TABLE hakim_fixture_before ON COMMIT DROP AS SELECT id,to_jsonb(f)-'home_team_id'-'away_team_id'-'updated_at'-'schedule_version' preserved,schedule_version FROM public.fixtures f WHERE id IN(SELECT id FROM hakim_changes);
INSERT INTO public.teams(id,competition_season_id,legacy_id,name,kit_colour) VALUES('f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c','62ce7ec9-459e-4acf-bec5-c6734a3199ef','mon-hakims-team','Hakim''s Team','#FFFFFF');
INSERT INTO public.team_fixture_notes(team_id,notes) VALUES('f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c','Organiser-confirmed 6 November 2026: new temporary Hakim''s Team identity replaces Imole United in Monday Division A, 2026 - Season 2; inherits its three results and remaining fixture place. 9 November at 19:40 against Ghazni is confirmed. Organiser confirms white shirt and no current kickoff restrictions on 6 November 2026. Availability may change later; update through Teams.');
UPDATE public.teams SET status='replaced',standings_eligible=false,profile_version=profile_version+1 WHERE id='aae18510-0f33-494b-8962-d7a5e86d0bf0';
UPDATE public.fixtures f SET home_team_id=c.home_team_id,away_team_id=c.away_team_id FROM hakim_changes c WHERE f.id=c.id;
DO $$ BEGIN
 IF (SELECT count(*)FROM public.teams WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status='active' AND standings_eligible)<>16 THEN RAISE EXCEPTION 'Expected 16 active teams'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.standings WHERE team_id='f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c' AND played=3 AND wins=0 AND draws=0 AND losses=3 AND goals_for=3 AND goals_against=21 AND points=0) THEN RAISE EXCEPTION 'Hakim inherited standings mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' AND 'aae18510-0f33-494b-8962-d7a5e86d0bf0' IN(home_team_id,away_team_id)) THEN RAISE EXCEPTION 'Imole remains in active schedule'; END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' GROUP BY least(home_team_id,away_team_id),greatest(home_team_id,away_team_id) HAVING count(*)<>2) OR (SELECT count(*) FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled')<>240 THEN RAISE EXCEPTION 'Every pair must meet twice across 240 fixtures'; END IF;
 IF EXISTS(SELECT round_number,t FROM public.fixtures f CROSS JOIN LATERAL unnest(array[f.home_team_id,f.away_team_id])t WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' GROUP BY round_number,t HAVING count(*)<>1) THEN RAISE EXCEPTION 'Team appears more than once per round'; END IF;
 IF EXISTS(SELECT t FROM public.fixtures f CROSS JOIN LATERAL unnest(array[f.home_team_id,f.away_team_id])t WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' GROUP BY t HAVING count(*)<>30 OR count(*)FILTER(WHERE home_team_id=t)<>15) THEN RAISE EXCEPTION 'Expected 30 matches and 15 home per team'; END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' AND (('bd834936-1b8a-4dd7-9013-d4b792862b67' IN(home_team_id,away_team_id) AND kickoff_time NOT IN('19:00','19:40')) OR ('544ff92b-0753-4e4f-9feb-bdcdf9c74a98' IN(home_team_id,away_team_id) AND kickoff_time='19:00'))) THEN RAISE EXCEPTION 'Hard availability violation'; END IF;
 IF EXISTS(SELECT round_number,kickoff_time FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' AND (home_team_id IN('d16662f1-9520-4f2a-b30b-ede1db30f28d','997291fd-33ff-40cc-9fd8-be732f6e07ca') OR away_team_id IN('d16662f1-9520-4f2a-b30b-ede1db30f28d','997291fd-33ff-40cc-9fd8-be732f6e07ca')) GROUP BY round_number,kickoff_time HAVING count(*)>1) THEN RAISE EXCEPTION 'Goldlink/Buckle simultaneous kickoff'; END IF;
 IF EXISTS(SELECT 1 FROM hakim_fixture_before b JOIN public.fixtures f USING(id) WHERE b.preserved IS DISTINCT FROM to_jsonb(f)-'home_team_id'-'away_team_id'-'updated_at'-'schedule_version' OR f.schedule_version<>b.schedule_version+1) THEN RAISE EXCEPTION 'Unapproved fixture field/version change'; END IF;
 IF EXISTS(SELECT 1 FROM hakim_audit_before b LEFT JOIN public.admin_audit_log a USING(id) WHERE b.preserved IS DISTINCT FROM to_jsonb(a)) THEN RAISE EXCEPTION 'Existing audit records changed'; END IF;
 IF EXISTS(SELECT 1 FROM hakim_protected p JOIN (select 'results' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.result_versions x where true
union all
select 'fixtures' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.fixtures x where id not in(select id from hakim_changes)
union all
select 'teams' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.teams x where id<>'aae18510-0f33-494b-8962-d7a5e86d0bf0' and id<>'f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c'
union all
select 'adjustments' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.standing_adjustments x where true
union all
select 'preferences' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.team_kickoff_preferences x where true
union all
select 'notes' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by team_id)::text,'[]')) hash from public.team_fixture_notes x where team_id<>'f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c'
union all
select 'editions' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.competition_seasons x where true
union all
select 'seasons' kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]')) hash from public.seasons x where true) a USING(kind) WHERE p.hash IS DISTINCT FROM a.hash) THEN RAISE EXCEPTION 'Protected records changed'; END IF;
END $$;
COMMIT;
